SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
START TRANSACTION;
SET time_zone = "+00:00";

/*!40101 SET @OLD_CHARACTER_SET_CLIENT=@@CHARACTER_SET_CLIENT */;
/*!40101 SET @OLD_CHARACTER_SET_RESULTS=@@CHARACTER_SET_RESULTS */;
/*!40101 SET @OLD_COLLATION_CONNECTION=@@COLLATION_CONNECTION */;
/*!40101 SET NAMES utf8mb4 */;

CREATE DATABASE IF NOT EXISTS `supinfo_phpd1` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE 'supinfo_phpd1`;
SET FOREIGN_KEY_CHECKS = 0;

-- Suppression des tables existantes, dans l'ordre inverse des dépendances
DROP TABLE IF EXISTS `achats`;
DROP TABLE IF EXISTS `panier`;
DROP TABLE IF EXISTS `commandes`;
DROP TABLE IF EXISTS `films`;
DROP TABLE IF EXISTS `categories`;
DROP TABLE IF EXISTS `utilisateurs`;

CREATE TABLE IF NOT EXISTS `achats` (
  `id_commande` int(11) NOT NULL,
  `imdb_id` varchar(12) NOT NULL,
  `prix_paye` decimal(8,2) NOT NULL,
  PRIMARY KEY (`id_commande`,`imdb_id`),
  KEY `imdb_id` (`imdb_id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `categories` (
  `id` int(11) NOT NULL,
  `nom` varchar(50) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `nom` (`nom`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT INTO `categories` (`id`, `nom`) VALUES
(1, 'Drame'),
(2, 'Action'),
(3, 'Science-fiction'),
(4, 'Thriller / Crime'),
(5, 'Animation');

CREATE TABLE IF NOT EXISTS `commandes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_utilisateur` int(11) NOT NULL,
  `date_commande` timestamp NOT NULL DEFAULT current_timestamp(),
  `total` decimal(8,2) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `id_utilisateur` (`id_utilisateur`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `films` (
  `imdb_id` varchar(12) NOT NULL,
  `titre` varchar(255) NOT NULL,
  `annee` int(11) DEFAULT NULL,
  `classification` varchar(20) DEFAULT NULL,
  `date_sortie` date DEFAULT NULL,
  `duree_min` int(11) DEFAULT NULL,
  `genres` varchar(255) DEFAULT NULL,
  `realisateur` text DEFAULT NULL,
  `scenaristes` text DEFAULT NULL,
  `acteurs` text DEFAULT NULL,
  `synopsis` text DEFAULT NULL,
  `langues` varchar(255) DEFAULT NULL,
  `pays` varchar(255) DEFAULT NULL,
  `recompenses` text DEFAULT NULL,
  `affiche_url` text DEFAULT NULL,
  `affiche_locale` text DEFAULT NULL,
  `metascore` int(11) DEFAULT NULL,
  `note_imdb` decimal(3,1) DEFAULT NULL,
  `votes_imdb` int(11) DEFAULT NULL,
  `type` varchar(20) DEFAULT NULL,
  `dvd` varchar(50) DEFAULT NULL,
  `box_office_usd` bigint(20) DEFAULT NULL,
  `production` varchar(255) DEFAULT NULL,
  `site_web` text DEFAULT NULL,
  `categorie_id` int(11) NOT NULL,
  PRIMARY KEY (`imdb_id`),
  KEY `categorie_id` (`categorie_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT INTO `films` (`imdb_id`, `titre`, `annee`, `classification`, `date_sortie`, `duree_min`, `genres`, `realisateur`, `scenaristes`, `acteurs`, `synopsis`, `langues`, `pays`, `recompenses`, `affiche_url`, `affiche_locale`, `metascore`, `note_imdb`, `votes_imdb`, `type`, `dvd`, `box_office_usd`, `production`, `site_web`, `categorie_id`) VALUES
('tt0102926', 'The Silence of the Lambs', 1991, 'R', '1991-02-14', 118, 'Crime, Drama, Horror', 'Jonathan Demme', 'Thomas Harris, Ted Tally', 'Jodie Foster, Anthony Hopkins, Scott Glenn', 'F.B.I. trainee Clarice Starling (Jodie Foster) works hard to advance her career, while trying to hide or put behind her West Virginia roots, of which if some knew, would automatically classify her as being backward or white trash. After graduation, she aspires to work in the agency\'s Behavioral Science Unit under the leadership of Jack Crawford (Scott Glenn). While she is still a trainee, Crawford asks her to question Dr. Hannibal Lecter (Sir Anthony Hopkins), a psychiatrist imprisoned, thus far, for eight years in maximum security isolation for being a serial killer who cannibalized his victims. Clarice is able to figure out the assignment is to pick Lecter\'s brains to help them solve another serial murder case, that of someone coined by the media as \"Buffalo Bill\" (Ted Levine), who has so far killed five victims, all located in the eastern U.S., all young women, who are slightly overweight (especially around the hips), all who were drowned in natural bodies of water, and all who were stripped of large swaths of skin. She also figures that Crawford chose her, as a woman, to be able to trigger some emotional response from Lecter. After speaking to Lecter for the first time, she realizes that everything with him will be a psychological game, with her often having to read between the very cryptic lines he provides. She has to decide how much she will play along, as his request in return for talking to him is to expose herself emotionally to him. The case takes a more dire turn when a sixth victim is discovered, this one from who they are able to retrieve a key piece of evidence, if Lecter is being forthright as to its meaning. A potential seventh victim is high profile Catherine Martin (Brooke Smith), the daughter of Senator Ruth Martin (Diane Baker), which places greater scrutiny on the case as they search for a hopefully still alive Catherine. Who may factor into what happens is Dr. Frederick Chilton (Anthony Heald), the warden at the prison, an opportunist who sees the higher profile with Catherine, meaning a higher profile for himself if he can insert himself successfully into the proceedings.', 'English, Latin', 'United States', 'Won 5 Oscars. 71 wins & 50 nominations total', 'https://m.media-amazon.com/images/M/MV5BNDdhOGJhYzctYzYwZC00YmI2LWI0MjctYjg4ODdlMDExYjBlXkEyXkFqcGc@._V1_QL75_UY562_CR1,0,380,562_.jpg', NULL, 86, 8.6, 1755718, 'movie', NULL, 131138318, NULL, NULL, 4),
('tt0103064', 'Terminator 2: Judgment Day', 1991, 'R', '1991-07-03', 137, 'Action, Adventure, Sci-Fi', 'James Cameron', 'James Cameron, William Wisher', 'Arnold Schwarzenegger, Linda Hamilton, Edward Furlong', 'Over ten years have passed since the first machine called The Terminator tried to kill Sarah Connor and her unborn son, John. The man who will become the future leader of the human resistance against the Machines is now a healthy young boy. However, another Terminator, called the T-1000, is sent back through time by the self-aware computer system, Skynet. This new Terminator is more advanced and more powerful than its predecessor and its mission is to kill John Connor when he\'s still a child. However, Sarah and John do not have to face the threat of the T-1000 alone. Another Terminator (identical to the same model that tried and failed to kill Sarah Connor in 1984) is also sent back through time to protect them. While John teaches the Terminator about humanity, Sarah tries to prevent the creation of Skynet and the Machines.', 'English, Spanish', 'United States, France', 'Won 4 Oscars. 39 wins & 33 nominations total', 'https://m.media-amazon.com/images/M/MV5BNGMyMGNkMDUtMjc2Ni00NWFlLTgyODEtZTY2MzBiZTg0OWZiXkEyXkFqcGc@._V1_QL75_UX380_CR0,1,380,562_.jpg', NULL, 75, 8.6, 1304963, 'movie', NULL, 206970218, NULL, NULL, 2),
('tt0109830', 'Forrest Gump', 1994, 'PG-13', '1994-07-06', 142, 'Drama, Romance', 'Robert Zemeckis', 'Winston Groom, Eric Roth', 'Tom Hanks, Robin Wright, Gary Sinise', 'Forrest Gump is a simple man with a low I.Q. but good intentions. He is running through childhood with his best and only friend Jenny. His \'mama\' teaches him the ways of life and leaves him to choose his destiny. Forrest joins the army for service in Vietnam, finding new friends called Dan and Bubba, he wins medals, creates a famous shrimp fishing fleet, inspires people to jog, starts a ping-pong craze, creates the smiley, writes bumper stickers and songs, donates to people and meets the president several times. However, this is all irrelevant to Forrest who can only think of his childhood sweetheart Jenny Curran, who has messed up her life. Although in the end all he wants to prove is that anyone can love anyone.', 'English', 'United States', 'Won 6 Oscars. 51 wins & 74 nominations total', 'https://m.media-amazon.com/images/M/MV5BNDYwNzVjMTItZmU5YS00YjQ5LTljYjgtMjY2NDVmYWMyNWFmXkEyXkFqcGc@._V1_QL75_UY562_CR4,0,380,562_.jpg', NULL, 82, 8.8, 2542224, 'movie', NULL, 330455270, NULL, NULL, 1),
('tt0110357', 'The Lion King', 1994, 'G', '1994-06-24', 88, 'Animation, Adventure, Drama', 'Roger Allers, Rob Minkoff', 'Irene Mecchi, Jonathan Roberts, Linda Woolverton', 'Matthew Broderick, Jeremy Irons, James Earl Jones', 'A young lion prince is cast out of his pride by his cruel uncle, who claims he killed his father. While the uncle rules with an iron paw, the prince grows up beyond the Savannah, living by a philosophy: No worries for the rest of your days. But when his past comes to haunt him, the young prince must decide his fate: Will he remain an outcast or face his demons and become what he needs to be?', 'English, Swahili, Xhosa, Zulu', 'United States', 'Won 2 Oscars. 43 wins & 35 nominations total', 'https://m.media-amazon.com/images/M/MV5BZGRiZDZhZjItM2M3ZC00Y2IyLTk3Y2MtMWY5YjliNDFkZTJlXkEyXkFqcGc@._V1_QL75_UX380_CR0,1,380,562_.jpg', NULL, 88, 8.5, 1280687, 'movie', NULL, 424979720, NULL, NULL, 5),
('tt0110413', 'Léon: The Professional', 1994, 'R', '1994-11-18', 110, 'Action, Crime, Drama', 'Luc Besson', 'Luc Besson', 'Jean Reno, Gary Oldman, Natalie Portman', 'After her father, step-mother, step-sister and little brother are killed by her father\'s employers, the 12-year-old daughter of an abject drug dealer manages to take refuge in the apartment of a professional hitman who at her request teaches her the methods of his job so she can take her revenge on the corrupt DEA agent who ruined her life by killing her beloved brother.', 'English, Italian, French', 'France, United States', '5 wins & 16 nominations total', 'https://m.media-amazon.com/images/M/MV5BNGRkYTNhOWQtYmI0Ni00MjZhLWJmMzAtMTA2Mjg4NGNiNDU0XkEyXkFqcGc@._V1_QL75_UX380_CR0,2,380,562_.jpg', NULL, 64, 8.5, 1368735, 'movie', NULL, 19501238, NULL, NULL, 4),
('tt0110912', 'Pulp Fiction', 1994, 'R', '1994-10-14', 154, 'Crime, Drama', 'Quentin Tarantino', 'Quentin Tarantino, Roger Avary', 'John Travolta, Uma Thurman, Samuel L. Jackson', 'Jules Winnfield (Samuel L. Jackson) and Vincent Vega (John Travolta) are two hitmen who are out to retrieve a suitcase stolen from their employer, mob boss Marsellus Wallace (Ving Rhames). Wallace has also asked Vincent to take his wife Mia (Uma Thurman) out a few days later when Wallace himself will be out of town. Butch Coolidge (Bruce Willis) is an aging boxer who is paid by Wallace to lose his fight. The lives of these seemingly unrelated people are woven together comprising of a series of funny, bizarre and uncalled-for incidents.', 'English, Spanish, French', 'United States', 'Won 1 Oscar. 69 wins & 73 nominations total', 'https://m.media-amazon.com/images/M/MV5BYTViYTE3ZGQtNDBlMC00ZTAyLTkyODMtZGRiZDg0MjA2YThkXkEyXkFqcGc@._V1_QL75_UY562_CR3,0,380,562_.jpg', NULL, 95, 8.8, 2473737, 'movie', NULL, 107928762, NULL, NULL, 4),
('tt0111161', 'The Shawshank Redemption', 1994, 'R', '1994-10-14', 142, 'Drama', 'Frank Darabont', 'Stephen King, Frank Darabont', 'Tim Robbins, Morgan Freeman, Bob Gunton', 'Chronicles the experiences of a formerly successful banker as a prisoner in the gloomy jailhouse of Shawshank after being found guilty of a crime he did not commit. The film portrays the man\'s unique way of dealing with his new, torturous life; along the way he befriends a number of fellow prisoners, most notably a wise long-term inmate named Red.', 'English', 'United States', 'Nominated for 7 Oscars. 21 wins & 43 nominations total', 'https://m.media-amazon.com/images/M/MV5BMDAyY2FhYjctNDc5OS00MDNlLThiMGUtY2UxYWVkNGY2ZjljXkEyXkFqcGc@._V1_QL75_UX380_CR0,4,380,562_.jpg', NULL, 82, 9.3, 3235958, 'movie', NULL, 28767189, NULL, NULL, 1),
('tt0112573', 'Braveheart', 1995, 'R', '1995-05-24', 178, 'Drama, War', 'Mel Gibson', 'Randall Wallace', 'Mel Gibson, Sophie Marceau, Patrick McGoohan', 'William Wallace is a Scottish rebel who leads an uprising against the cruel English ruler Edward Longshanks, who wishes to inherit the crown of Scotland for himself. When he was a young boy, William Wallace\'s father and brother, along with many others, lost their lives trying to free Scotland. Once he loses another of his loved ones, William Wallace begins his long quest to make Scotland free once and for all, along with the assistance of Robert the Bruce.', 'English, French, Latin, Gaelic, Italian', 'United States', 'Won 5 Oscars. 34 wins & 34 nominations total', 'https://m.media-amazon.com/images/M/MV5BNGMxZDBhNGQtYTZlNi00N2UzLWI4NDEtNmUzNWM2NTdmZDA0XkEyXkFqcGc@._V1_QL75_UY562_CR1,0,380,562_.jpg', NULL, 68, 8.3, 1174005, 'movie', NULL, 75609945, NULL, NULL, 2),
('tt0114709', 'Toy Story', 1995, 'G', '1995-11-22', 81, 'Animation, Adventure, Comedy', 'John Lasseter', 'John Lasseter, Pete Docter, Andrew Stanton', 'Tom Hanks, Tim Allen, Don Rickles', 'A little boy named Andy loves to be in his room, playing with his toys, especially his doll named \"Woody\". But, what do the toys do when Andy is not with them, they come to life. Woody believes that his life (as a toy) is good. However, he must worry about Andy\'s family moving, and what Woody does not know is about Andy\'s birthday party. Woody does not realize that Andy\'s mother gave him an action figure known as Buzz Lightyear, who does not believe that he is a toy, and quickly becomes Andy\'s new favorite toy. Woody, who is now consumed with jealousy, tries to get rid of Buzz. Then, both Woody and Buzz are now lost. They must find a way to get back to Andy before he moves without them, but they will have to pass through a ruthless toy killer, Sid Phillips.', 'English', 'United States', 'Nominated for 3 Oscars. 29 wins & 24 nominations total', 'https://m.media-amazon.com/images/M/MV5BZTA3OWVjOWItNjE1NS00NzZiLWE1MjgtZDZhMWI1ZTlkNzYwXkEyXkFqcGc@._V1_QL75_UX380_CR0,2,380,562_.jpg', NULL, 96, 8.3, 1202148, 'movie', NULL, 229947062, NULL, NULL, 5),
('tt0114814', 'The Usual Suspects', 1995, 'R', '1995-08-16', 106, 'Crime, Drama, Mystery', 'Bryan Singer', 'Christopher McQuarrie', 'Kevin Spacey, Gabriel Byrne, Chazz Palminteri', 'Following a truck hijack in New York, five criminals are arrested and brought together for questioning. As none of them are guilty, they plan a revenge operation against the police. The operation goes well, but then the influence of a legendary mastermind criminal called Keyser Söze is felt. It becomes clear that each one of them has wronged Söze at some point and must pay back now. The payback job leaves 27 men dead in a boat explosion, but the real question arises now: Who actually is Keyser Söze?', 'English, Hungarian, Spanish, French', 'United States, Germany', 'Won 2 Oscars. 37 wins & 17 nominations total', 'https://m.media-amazon.com/images/M/MV5BOTE5MDUxZDUtZWZmZC00NDVmLWFhOGQtNWI2YTc4NzY3MGQ0XkEyXkFqcGc@._V1_QL75_UX380_CR0,2,380,562_.jpg', NULL, 76, 8.5, 1257343, 'movie', NULL, 23341568, NULL, NULL, 4),
('tt0118799', 'Life Is Beautiful', 1997, 'PG-13', '1997-12-20', 116, 'Comedy, Drama, Romance', 'Roberto Benigni', 'Vincenzo Cerami, Roberto Benigni', 'Roberto Benigni, Nicoletta Braschi, Giorgio Cantarini', 'In 1930s Italy, a carefree Jewish waiter-turned-bookseller named Guido starts a fairy tale life by courting and marrying a lovely woman teacher named Dora. Guido and Dora have a son named Joshua and live happily together until the forced deportation of the town\'s Jewish population in cattle cars. Dora, while not required to be deported, volunteers to leave with her family, and they are all forced to live in a concentration camp. In an attempt to hold his family together and help his son survive the horrors of a concentration camp, Guido imagines that the Holocaust is a game and that the grand prize for winning is a tank.', 'Italian, German, English', 'Italy', 'Won 3 Oscars. 72 wins & 52 nominations total', 'https://m.media-amazon.com/images/M/MV5BZTBhOGYzZjQtYzE0Mi00MGIwLWE0MWYtNzMxNTM2OTFkM2NjXkEyXkFqcGc@._V1_QL75_UX380_CR0,2,380,562_.jpg', NULL, 58, 8.6, 822861, 'movie', NULL, 57563264, NULL, NULL, 1),
('tt0119698', 'Princess Mononoke', 1997, 'PG-13', '1997-07-12', 133, 'Animation, Adventure, Fantasy', 'Hayao Miyazaki', 'Hayao Miyazaki', 'Yôji Matsuda, Yuriko Ishida, Yûko Tanaka', 'While protecting his village from rampaging boar-god/demon, a confident young warrior, Ashitaka, is stricken by a deadly curse. To save his life, he must journey to the forests of the west. Once there, he\'s embroiled in a fierce campaign that humans were waging on the forest. The ambitious Lady Eboshi and her loyal clan use their guns against the gods of the forest and a brave young woman, Princess Mononoke, who was raised by a wolf-god. Ashitaka sees the good in both sides and tries to stem the flood of blood. This is met by animosity by both sides as they each see him as supporting the enemy.', 'Japanese', 'Japan', '14 wins & 6 nominations total', 'https://m.media-amazon.com/images/M/MV5BZTcyN2Y0MDYtMGI1NC00MWQ1LWFhZGMtN2U4NTcxZGYyNjljXkEyXkFqcGc@._V1_QL75_UX380_CR0,4,380,562_.jpg', NULL, 78, 8.3, 492213, 'movie', NULL, 12544202, NULL, NULL, 5),
('tt0120586', 'American History X', 1998, 'R', '1998-11-20', 119, 'Crime, Drama', 'Tony Kaye', 'David McKenna', 'Edward Norton, Edward Furlong, Beverly D&apos;Angelo', 'Derek Vineyard is paroled after serving 3 years in prison for brutally killing two black men who tried to break into/steal his truck. Through his 14 yr old brother\'s, Danny Vineyard, narration, we learn that before going to prison, Derek was a skinhead and the leader of a violent white supremacist gang that committed acts of racial crime throughout L.A. and his actions greatly influenced Danny. Reformed and fresh out of prison, Derek severs contact with the gang and becomes determined to keep Danny from going down the same violent path as he did.', 'English', 'United States', 'Nominated for 1 Oscar. 4 wins & 15 nominations total', 'https://m.media-amazon.com/images/M/MV5BMzhiOTQ0NDItOTg0Zi00OGVmLWE0OGEtMTI4NDM0NWMxZWU4XkEyXkFqcGc@._V1_QL75_UX380_CR0,1,380,562_.jpg', NULL, 62, 8.5, 1289228, 'movie', NULL, 6719864, NULL, NULL, 1),
('tt0120689', 'The Green Mile', 1999, 'R', '1999-12-10', 189, 'Crime, Drama, Fantasy', 'Frank Darabont', 'Stephen King, Frank Darabont', 'Tom Hanks, Michael Clarke Duncan, David Morse', 'Based on Stephen King\'s 1996 novel of the same name. Stars Tom Hanks as a death row corrections officer during the U.S. Great Depression who witnesses supernatural events that occur after an enigmatic inmate (Michael Clarke Duncan) is brought to his facility.', 'English, French', 'United States', 'Nominated for 4 Oscars. 15 wins & 37 nominations total', 'https://m.media-amazon.com/images/M/MV5BMTUxMzQyNjA5MF5BMl5BanBnXkFtZTYwOTU2NTY3._V1_QL75_UX380_CR0,0,380,562_.jpg', NULL, 61, 8.6, 1590001, 'movie', NULL, 136801374, NULL, NULL, 1),
('tt0120737', 'The Lord of the Rings: The Fellowship of the Ring', 2001, 'PG-13', '2001-12-19', 178, 'Adventure, Drama, Fantasy', 'Peter Jackson', 'J.R.R. Tolkien, Fran Walsh, Philippa Boyens', 'Elijah Wood, Ian McKellen, Orlando Bloom', 'In the first part of J.R.R. Tolkien\'s epic masterpiece, The Lord of the Rings, a shy young hobbit named Frodo Baggins inherits a simple gold ring. He knows the ring has power, but not that he alone holds the secret to the survival--or enslavement--of the entire world. Now Frodo, accompanied by a wizard, an elf, a dwarf, two men and three loyal hobbit friends, must become the greatest hero the world has ever known to save the land and the people he loves.', 'English, Sindarin', 'New Zealand, United States', 'Won 4 Oscars. 126 wins & 127 nominations total', 'https://m.media-amazon.com/images/M/MV5BNzIxMDQ2YTctNDY4MC00ZTRhLTk4ODQtMTVlOWY4NTdiYmMwXkEyXkFqcGc@._V1_QL75_UX380_CR0,1,380,562_.jpg', NULL, 92, 8.9, 2242919, 'movie', NULL, 325873309, NULL, NULL, 2),
('tt0133093', 'The Matrix', 1999, 'R', '1999-03-31', 136, 'Action, Sci-Fi', 'Lana Wachowski, Lilly Wachowski', 'Lilly Wachowski, Lana Wachowski', 'Keanu Reeves, Laurence Fishburne, Carrie-Anne Moss', 'Thomas A. Anderson is a man living two lives. By day he is an average computer programmer and by night a hacker known as Neo. Neo has always questioned his reality, but the truth is far beyond his imagination. Neo finds himself targeted by the police when he is contacted by Morpheus, a legendary computer hacker branded a terrorist by the government. As a rebel against the machines, Neo must confront the agents: super-powerful computer programs devoted to stopping Neo and the entire human rebellion.', 'English', 'United States', 'Won 4 Oscars. 42 wins & 52 nominations total', 'https://m.media-amazon.com/images/M/MV5BN2NmN2VhMTQtMDNiOS00NDlhLTliMjgtODE2ZTY0ODQyNDRhXkEyXkFqcGc@._V1_QL75_UX380_CR0,4,380,562_.jpg', NULL, 73, 8.7, 2284373, 'movie', NULL, 177559005, NULL, NULL, 3),
('tt0137523', 'Fight Club', 1999, 'R', '1999-10-15', 139, 'Crime, Drama, Thriller', 'David Fincher', 'Chuck Palahniuk, Jim Uhls', 'Brad Pitt, Edward Norton, Meat Loaf', 'A nameless first-person narrator attends support groups in an attempt to subdue his emotional state and relieve his insomniac state. When he meets Marla, another fake attendee of support groups, his life seems to become a little more bearable. However, when he associates himself with Tyler he is dragged into an underground fight club and soap-making scheme. Together the two men spiral out of control and engage in competitive rivalry for love and power.', 'English', 'United States, Germany', 'Nominated for 1 Oscar. 12 wins & 38 nominations total', 'https://m.media-amazon.com/images/M/MV5BOTgyOGQ1NDItNGU3Ny00MjU3LTg2YWEtNmEyYjBiMjI1Y2M5XkEyXkFqcGc@._V1_QL75_UX380_CR0,4,380,562_.jpg', NULL, 67, 8.8, 2669989, 'movie', NULL, 38003039, NULL, NULL, 4),
('tt0167260', 'The Lord of the Rings: The Return of the King', 2003, 'PG-13', '2003-12-17', 201, 'Adventure, Drama, Fantasy', 'Peter Jackson', 'J.R.R. Tolkien, Fran Walsh, Philippa Boyens', 'Elijah Wood, Viggo Mortensen, Ian McKellen', '\"One ring to rule them all. One ring to find them. One ring to bring them all and in the darkness bind them.\" In the conclusion of J.R.R. Tolkien\'s epic masterpiece, The Lord of the Rings, as armies mass for a final battle that will decide the fate of the world--and powerful, ancient forces of Light and Dark compete to determine the outcome--one member of the Fellowship of the Ring is revealed as the noble heir to the throne of the Kings of Men. Yet, the sole hope for triumph over evil lies with a brave hobbit, Frodo, who, accompanied only by his loyal friend Sam and the hideous, wretched Gollum, ventures deep into the very dark heart of Mordor on his seemingly impossible quest to destroy the Ring of Power.', 'English, Quenya, Old English, Sindarin', 'New Zealand, United States', 'Won 11 Oscars. 215 wins & 124 nominations total', 'https://m.media-amazon.com/images/M/MV5BMTZkMjBjNWMtZGI5OC00MGU0LTk4ZTItODg2NWM3NTVmNWQ4XkEyXkFqcGc@._V1_QL75_UX380_CR0,0,380,562_.jpg', NULL, 94, 9.0, 2198979, 'movie', NULL, 386975644, NULL, NULL, 2),
('tt0167261', 'The Lord of the Rings: The Two Towers', 2002, 'PG-13', '2002-12-18', 179, 'Adventure, Drama, Fantasy', 'Peter Jackson', 'J.R.R. Tolkien, Fran Walsh, Philippa Boyens', 'Elijah Wood, Ian McKellen, Viggo Mortensen', 'In the second part of the Tolkien trilogy, Frodo Baggins and the other members of the Fellowship continue on their sacred quest to destroy the One Ring--but on separate paths. Their destinies lie at two towers--Orthanc Tower in Isengard, where the corrupt wizard Saruman awaits, and Sauron\'s fortress at Barad-dur, deep within the dark lands of Mordor.', 'English, Sindarin, Old English', 'New Zealand, United States', 'Won 2 Oscars. 132 wins & 139 nominations total', 'https://m.media-amazon.com/images/M/MV5BMGQxMDdiOWUtYjc1Ni00YzM1LWE2NjMtZTg3Y2JkMjEzMTJjXkEyXkFqcGc@._V1_QL75_UX380_CR0,14,380,562_.jpg', NULL, 87, 8.8, 1988975, 'movie', NULL, 350104956, NULL, NULL, 2),
('tt0172495', 'Gladiator', 2000, 'R', '2000-05-05', 155, 'Action, Adventure, Drama', 'Ridley Scott', 'David Franzoni, John Logan, William Nicholson', 'Russell Crowe, Joaquin Phoenix, Connie Nielsen', 'Maximus is a powerful Roman general, loved by the people and the aging Emperor, Marcus Aurelius. Before his death, the Emperor chooses Maximus to be his heir over his own son, Commodus, and a power struggle leaves Maximus and his family condemned to death. The powerful general is captured and put into the Gladiator games until he dies. The only desire that fuels him now is the chance to rise to the top so that he will be able to look into the eyes of the man who will feel his revenge.', 'English', 'United Kingdom, Malta, Morocco, United States', 'Won 5 Oscars. 61 wins & 105 nominations total', 'https://m.media-amazon.com/images/M/MV5BYWQ4YmNjYjEtOWE1Zi00Y2U4LWI4NTAtMTU0MjkxNWQ1ZmJiXkEyXkFqcGc@._V1_QL75_UX380_CR0,0,380,562_.jpg', NULL, 67, 8.5, 1886962, 'movie', NULL, 187705427, NULL, NULL, 2),
('tt0181689', 'Minority Report', 2002, 'PG-13', '2002-06-21', 145, 'Action, Crime, Mystery', 'Steven Spielberg', 'Scott Frank, Jon Cohen, Philip K. Dick', 'Tom Cruise, Colin Farrell, Samantha Morton', 'In the year 2054 A.D. crime is virtually eliminated from Washington D.C. thanks to an elite law enforcing squad \"Precrime\". They use three gifted humans (called \"Pre-Cogs\") with special powers to see into the future and predict crimes beforehand. John Anderton heads Precrime and believes the system\'s flawlessness steadfastly. However one day the Pre-Cogs predict that Anderton will commit a murder himself in the next 36 hours. Worse, Anderton doesn\'t even know the victim. He decides to get to the mystery\'s core by finding out the \'minority report\' which means the prediction of the female Pre-Cog Agatha that \"might\" tell a different story and prove Anderton innocent.', 'English, Swedish', 'United States', 'Nominated for 1 Oscar. 20 wins & 91 nominations total', 'https://m.media-amazon.com/images/M/MV5BYTdmNzM3YzItZTRkYS00MTY5LTg4ZmItNjFmNTk2N2Q2NmNlXkEyXkFqcGc@._V1_QL75_UX380_CR0,4,380,562_.jpg', NULL, 80, 7.6, 628233, 'movie', NULL, 132072926, NULL, NULL, 3),
('tt0266543', 'Finding Nemo', 2003, 'G', '2003-05-30', 100, 'Animation, Adventure, Comedy', 'Andrew Stanton, Lee Unkrich', 'Andrew Stanton, Bob Peterson, David Reynolds', 'Albert Brooks, Ellen DeGeneres, Alexander Gould', 'A clown fish named Marlin lives in the Great Barrier Reef and loses his son, Nemo, after he ventures into the open sea, despite his father\'s constant warnings about many of the ocean\'s dangers. Nemo is a boy abducted by a boat and netted up and sent to a dentist\'s office in Sydney. While Marlin ventures off to try to retrieve Nemo, Marlin meets a fish named Dory, a blue tang suffering from short-term memory loss. The companions travel a great distance, encountering various dangerous sea creatures such as sharks, anglerfish and jellyfish, in order to rescue Nemo from the dentist\'s office, which is situated by Sydney Harbour. While the two are searching the ocean far and wide, Nemo and the other sea animals in the dentist\'s fish tank plot a way to return to the sea to live their lives free again.', 'English', 'United States, Japan', 'Won 1 Oscar. 49 wins & 63 nominations total', 'https://m.media-amazon.com/images/M/MV5BMTc5NjExNTA5OV5BMl5BanBnXkFtZTYwMTQ0ODY2._V1_QL75_UX380_CR0,0,380,562_.jpg', NULL, 90, 8.2, 1227539, 'movie', NULL, 380843261, NULL, NULL, 5),
('tt0338013', 'Eternal Sunshine of the Spotless Mind', 2004, 'R', '2004-03-19', 108, 'Drama, Romance, Sci-Fi', 'Michel Gondry', 'Charlie Kaufman, Michel Gondry, Pierre Bismuth', 'Jim Carrey, Kate Winslet, Tom Wilkinson', 'Much to his surprise, timid Joel Barish is shocked to discover that the love of his life, sparky Clementine, has had him erased from her memory. As a result, hurt and angry, Joel wants to pay her back in the same coin, going as far as to undergo a painless but intricate medical procedure to do the same. However, poor Joel is utterly unaware that darkness is an essential part of the light. And as the once-cherished recollections of Clementine gradually fade away, giving way to a soulless black void, something unexpected happens. Now Joel has second thoughts, toying with the idea of stopping the irreversible process. Who said ignorance is bliss?', 'English', 'United States', 'Won 1 Oscar. 73 wins & 111 nominations total', 'https://m.media-amazon.com/images/M/MV5BMTY4NzcwODg3Nl5BMl5BanBnXkFtZTcwNTEwOTMyMw@@._V1_QL75_UX380_CR0,0,380,562_.jpg', NULL, 89, 8.3, 1198489, 'movie', NULL, 34400301, NULL, NULL, 3),
('tt0407887', 'The Departed', 2006, 'R', '2006-10-06', 151, 'Crime, Drama, Thriller', 'Martin Scorsese', 'William Monahan, Alan Mak, Felix Chong', 'Leonardo DiCaprio, Matt Damon, Jack Nicholson', 'The Massachusetts State Police is desperate to crack down on Irish-American organized crime. Young undercover cop Billy Costigan is assigned to infiltrate the mob syndicate run by Frank Costello. While Billy quickly gains Costello\'s confidence, Colin Sullivan, a protege of Costello who has infiltrated the state police as an informant for the syndicate, is rising to a position of power in the Special Investigation Unit. Each man becomes deeply consumed by their double lives, gathering information about the plans and counter-plans of the operations they have penetrated. But when it becomes clear to both the mob and the police that there is a mole in their midst, Billy and Colin are suddenly in danger of being caught and exposed to the enemy, and each must race to uncover the identity of the other man in time to save themselves.', 'English, Cantonese', 'United States, Hong Kong', 'Won 4 Oscars. 100 wins & 141 nominations total', 'https://m.media-amazon.com/images/M/MV5BMTI1MTY2OTIxNV5BMl5BanBnXkFtZTYwNjQ4NjY3._V1_QL75_UY562_CR0,0,380,562_.jpg', NULL, 85, 8.5, 1583117, 'movie', NULL, 132399394, NULL, NULL, 4),
('tt0468569', 'The Dark Knight', 2008, 'PG-13', '2008-07-18', 152, 'Crime, Thriller', 'Christopher Nolan', 'Jonathan Nolan, Christopher Nolan, David S. Goyer', 'Christian Bale, Heath Ledger, Aaron Eckhart', 'Set within a year after the events of Batman Begins (2005), Batman, Lieutenant James Gordon, and new District Attorney Harvey Dent successfully begin to round up the criminals that plague Gotham City, until a mysterious and sadistic criminal mastermind known only as \"The Joker\" appears in Gotham, creating a new wave of chaos. Batman\'s struggle against The Joker becomes deeply personal, forcing him to \"confront everything he believes\" and improve his technology to stop him. A love triangle develops between Bruce Wayne, Dent, and Rachel Dawes.', 'English, Mandarin', 'United States, United Kingdom', 'Won 2 Oscars. 164 wins & 165 nominations total', 'https://m.media-amazon.com/images/M/MV5BMTMxNTMwODM0NF5BMl5BanBnXkFtZTcwODAyMTk2Mw@@._V1_QL75_UX380_CR0,0,380,562_.jpg', NULL, 85, 9.1, 3236507, 'movie', NULL, 534987076, NULL, NULL, 2),
('tt0816692', 'Interstellar', 2014, 'PG-13', '2014-11-07', 169, 'Adventure, Sci-Fi', 'Christopher Nolan', 'Jonathan Nolan, Christopher Nolan', 'Matthew McConaughey, Anne Hathaway, Jessica Chastain', 'In the near future around the American Midwest, Cooper, an ex-science engineer and pilot, is tied to his farming land with his daughter Murph and son Tom. As devastating sandstorms ravage Earth\'s crops, the people of Earth realize their life here is coming to an end as food begins to run out. Eventually stumbling upon a N.A.S.A. base 6 hours from Cooper\'s home, he is asked to go on a daring mission with a few other scientists into a wormhole because of Cooper\'s scientific intellect and ability to pilot aircraft unlike the other crew members. In order to find a new home while Earth decays, Cooper must decide to either stay, or risk never seeing his children again in order to save the human race by finding another habitable planet.', 'English', 'United States, United Kingdom, Canada', 'Won 1 Oscar. 45 wins & 148 nominations total', 'https://m.media-amazon.com/images/M/MV5BYzdjMDAxZGItMjI2My00ODA1LTlkNzItOWFjMDU5ZDJlYWY3XkEyXkFqcGc@._V1_QL75_UX380_CR0,0,380,562_.jpg', NULL, 74, 8.7, 2617722, 'movie', NULL, 203227580, NULL, NULL, 3),
('tt1049413', 'Up', 2009, 'PG', '2009-05-29', 96, 'Animation, Adventure, Comedy', 'Pete Docter, Bob Peterson', 'Pete Docter, Bob Peterson, Tom McCarthy', 'Edward Asner, Jordan Nagai, John Ratzenberger', 'As a boy, Carl Fredricksen wanted to explore South America and find the forbidden Paradise Falls. About 64 years later he gets to begin his journey along with Boy Scout Russell by lifting his house with thousands of balloons. On their journey, they make many new friends including a talking dog, and figure out that someone has evil plans. Carl soon realizes that this evildoer is his childhood idol.', 'English', 'United States, Japan', 'Won 2 Oscars. 81 wins & 88 nominations total', 'https://m.media-amazon.com/images/M/MV5BNmI1ZTc5MWMtMDYyOS00ZDc2LTkzOTAtNjQ4NWIxNjYyNDgzXkEyXkFqcGc@._V1_QL75_UX380_CR0,1,380,562_.jpg', NULL, 88, 8.3, 1258840, 'movie', NULL, 293004164, NULL, NULL, 5),
('tt1160419', 'Dune', 2021, 'PG-13', '2021-10-22', 155, 'Action, Adventure, Drama', 'Denis Villeneuve', 'Jon Spaihts, Denis Villeneuve, Eric Roth', 'Timothée Chalamet, Rebecca Ferguson, Zendaya', 'A mythic and emotionally charged hero\'s journey, \"Dune\" tells the story of Paul Atreides, a brilliant and gifted young man born into a great destiny beyond his understanding, who must travel to the most dangerous planet in the universe to ensure the future of his family and his people. As malevolent forces explode into conflict over the planet\'s exclusive supply of the most precious resource in existence-a commodity capable of unlocking humanity\'s greatest potential-only those who can conquer their fear will survive.', 'English, Mandarin', 'Canada, United States', 'Won 6 Oscars. 177 wins & 299 nominations total', 'https://m.media-amazon.com/images/M/MV5BNWIyNmU5MGYtZDZmNi00ZjAwLWJlYjgtZTc0ZGIxMDE4ZGYwXkEyXkFqcGc@._V1_QL75_UY562_CR1,0,380,562_.jpg', NULL, 74, 8.0, 1094313, 'movie', NULL, 108897830, NULL, NULL, 3),
('tt1375666', 'Inception', 2010, 'PG-13', '2010-07-16', 148, 'Adventure, Sci-Fi, Thriller', 'Christopher Nolan', 'Christopher Nolan', 'Leonardo DiCaprio, Joseph Gordon-Levitt, Elliot Page', 'Dom Cobb is a skilled thief, the absolute best in the dangerous art of extraction, stealing valuable secrets from deep within the subconscious during the dream state, when the mind is at its most vulnerable. Cobb\'s rare ability has made him a coveted player in this treacherous new world of corporate espionage, but it has also made him an international fugitive and cost him everything he has ever loved. Now Cobb is being offered a chance at redemption. One last job could give him his life back but only if he can accomplish the impossible, inception. Instead of the perfect heist, Cobb and his team of specialists have to pull off the reverse: their task is not to steal an idea, but to plant one. If they succeed, it could be the perfect crime. But no amount of careful planning or expertise can prepare the team for the dangerous enemy that seems to predict their every move. An enemy that only Cobb could have seen coming.', 'English, Japanese, French', 'United Kingdom, United States', 'Won 4 Oscars. 160 wins & 220 nominations total', 'https://m.media-amazon.com/images/M/MV5BMjAxMzY3NjcxNF5BMl5BanBnXkFtZTcwNTI5OTM0Mw@@._V1_QL75_UX380_CR0,0,380,562_.jpg', NULL, 74, 8.8, 2877173, 'movie', NULL, 292587330, NULL, NULL, 3),
('tt1392190', 'Mad Max: Fury Road', 2015, 'R', '2015-05-15', 120, 'Action, Adventure, Sci-Fi', 'George Miller', 'George Miller, Brendan McCarthy, Nick Lathouris', 'Tom Hardy, Charlize Theron, Nicholas Hoult', 'An apocalyptic story set in the furthest reaches of our planet, in a stark desert landscape where humanity is broken, and almost everyone is crazed fighting for the necessities of life. Within this world exist two rebels on the run who just might be able to restore order. There\'s Max, a man of action and a man of few words, who seeks peace of mind following the loss of his wife and child in the aftermath of the chaos. And Furiosa, a woman of action and a woman who believes her path to survival may be achieved if she can make it across the desert back to her childhood homeland.', 'English, Russian', 'Australia, United States', 'Won 6 Oscars. 246 wins & 240 nominations total', 'https://m.media-amazon.com/images/M/MV5BZDRkODJhOTgtOTc1OC00NTgzLTk4NjItNDgxZDY4YjlmNDY2XkEyXkFqcGc@._V1_QL75_UX380_CR0,0,380,562_.jpg', NULL, 90, 8.1, 1223352, 'movie', NULL, 154280290, NULL, NULL, 2),
('tt1392214', 'Prisoners', 2013, 'R', '2013-09-20', 153, 'Crime, Drama, Mystery', 'Denis Villeneuve', 'Aaron Guzikowski', 'Hugh Jackman, Jake Gyllenhaal, Viola Davis', 'How far would you go to protect your family? Keller Dover is facing every parent\'s a lot of people worst nightmare. His six-year-old daughter, Anna, is missing, together with her young friend, Joy, and as minutes turn to hours, panic sets in. The only lead is a dilapidated RV that had earlier been parked on their street. Heading the investigation, Detective Loki arrests its driver, Alex Jones, but a lack of evidence forces his release. As the police pursue multiple leads and pressure mounts, knowing his child\'s life is at stake the frantic Dover decides he has no choice but to take matters into his own hands. But just how far will this desperate father go to protect his family?', 'English', 'United States', 'Nominated for 1 Oscar. 10 wins & 38 nominations total', 'https://m.media-amazon.com/images/M/MV5BMTg0NTIzMjQ1NV5BMl5BanBnXkFtZTcwNDc3MzM5OQ@@._V1_QL75_UY562_CR0,0,380,562_.jpg', NULL, 70, 8.2, 962336, 'movie', NULL, 61002302, NULL, NULL, 4),
('tt14055868', 'WALL-E: Treasures and Trinkets', 2008, 'TV-G', '2008-11-18', 5, 'Animation, Short', 'Andrew Stanton', NULL, NULL, 'A robot named WALL-E is on a uninhabitable earth by itself but when the human space ship comes and drops of a new robot named Eva on search for a plant. Eva meets WALL-E witch WALL-E shows Eva a plant. the humans come back to take Eva but when WALL-E comes along he will get to experience life of the human space ship for the first time.', 'English', 'United States', NULL, 'https://m.media-amazon.com/images/M/MV5BMzk0ZGMzMDYtMDJkYS00NTdhLWJlZWUtMTdhOTJkOTM3NDUwXkEyXkFqcGc@._V1_QL75_UX380_CR0,4,380,562_.jpg', NULL, NULL, 8.3, 1654, 'movie', NULL, NULL, NULL, NULL, 5),
('tt15239678', 'Dune: Part Two', 2024, 'PG-13', '2024-03-01', 166, 'Action, Adventure, Drama', 'Denis Villeneuve', 'Denis Villeneuve, Jon Spaihts, Frank Herbert', 'Timothée Chalamet, Zendaya, Rebecca Ferguson', 'Paul Atreides unites with Chani and the Fremen while on a warpath of revenge against the conspirators who destroyed his family. Facing a choice between the love of his life and the fate of the known universe, he endeavors to prevent a terrible future only he can foresee.', 'English, American Sign Language', 'United States, Canada, United Arab Emirates, Hungary, Italy, New Zealand, Jordan', 'Won 2 Oscars. 126 wins & 375 nominations total', 'https://m.media-amazon.com/images/M/MV5BNTc0YmQxMjEtODI5MC00NjFiLTlkMWUtOGQ5NjFmYWUyZGJhXkEyXkFqcGc@._V1_QL75_UX380_CR0,0,380,562_.jpg', NULL, 79, 8.4, 797737, 'movie', NULL, 282144358, NULL, NULL, 3),
('tt1856101', 'Blade Runner 2049', 2017, 'R', '2017-10-06', 164, 'Action, Drama, Mystery', 'Denis Villeneuve', 'Hampton Fancher, Michael Green, Philip K. Dick', 'Harrison Ford, Ryan Gosling, Ana de Armas', 'Thirty years after the events of Blade Runner (1982), a new Blade Runner, L.A.P.D. Officer \"K\" (Ryan Gosling), unearths a long-buried secret that has the potential to plunge what\'s left of society into chaos. K\'s discovery leads him on a quest to find Rick Deckard (Harrison Ford), a former L.A.P.D. Blade Runner, who has been missing for thirty years.', 'English', 'United States, Canada, Spain', 'Won 2 Oscars. 101 wins & 164 nominations total', 'https://m.media-amazon.com/images/M/MV5BNzA1Njg4NzYxOV5BMl5BanBnXkFtZTgwODk5NjU3MzI@._V1_QL75_UX380_CR0,0,380,562_.jpg', NULL, 81, 8.0, 769711, 'movie', NULL, 92071675, NULL, NULL, 3),
('tt2096673', 'Inside Out', 2015, 'PG', '2015-06-19', 95, 'Animation, Adventure, Comedy', 'Ronnie Del Carmen, Pete Docter', 'Pete Docter, Ronnie Del Carmen, Meg LeFauve', 'Amy Poehler, Bill Hader, Lewis Black', 'Growing up can be a bumpy road, and it\'s no exception for Riley, who is uprooted from her Midwest life when her father starts a new job in San Francisco. Like all of us, she is guided by her emotions, Joy, Fear, Anger, Disgust, and Sadness. They live in Headquarters, the control center inside her mind, where they help advise her through everyday life. As she and her emotions struggle to adjust to a new life in San Francisco, turmoil ensues in Headquarters. Although Joy tries to keep things positive, the emotions conflict on how best to navigate a new city, house, and school.', 'English, Portuguese, Latvian', 'United States, Japan', 'Won 1 Oscar. 99 wins & 120 nominations total', 'https://m.media-amazon.com/images/M/MV5BOTgxMDQwMDk0OF5BMl5BanBnXkFtZTgwNjU5OTg2NDE@._V1_QL75_UX380_CR0,0,380,562_.jpg', NULL, 94, 8.1, 935063, 'movie', NULL, 356461711, NULL, NULL, 5),
('tt2267998', 'Gone Girl', 2014, 'R', '2014-10-03', 149, 'Drama, Mystery, Thriller', 'David Fincher', 'Gillian Flynn', 'Ben Affleck, Rosamund Pike, Neil Patrick Harris', 'On the occasion of his fifth wedding anniversary, Nick Dunne reports that his wife, Amy, has gone missing. Under pressure from the police and a growing media frenzy, Nick\'s portrait of a blissful union begins to crumble. Soon his lies, deceits and strange behavior have everyone asking the same dark question: Did Nick Dunne kill his wife?', 'English', 'United States', 'Nominated for 1 Oscar. 65 wins & 192 nominations total', 'https://m.media-amazon.com/images/M/MV5BMTk0MDQ3MzAzOV5BMl5BanBnXkFtZTgwNzU1NzE3MjE@._V1_QL75_UY562_CR1,0,380,562_.jpg', NULL, 79, 8.1, 1190848, 'movie', NULL, 167767189, NULL, NULL, 4),
('tt2380307', 'Coco', 2017, 'PG', '2017-11-22', 105, 'Animation, Adventure, Drama', 'Adrian Molina, Lee Unkrich', 'Lee Unkrich, Jason Katz, Matthew Aldrich', 'Anthony Gonzalez, Gael García Bernal, Benjamin Bratt', 'Despite his family\'s baffling generations-old ban on music, Miguel dreams of becoming an accomplished musician like his idol, Ernesto de la Cruz. Desperate to prove his talent, Miguel finds himself in the stunning and colorful Land of the Dead following a mysterious chain of events. Along the way, he meets charming trickster Hector, and together, they set off on an extraordinary journey to unlock the real story behind Miguel\'s family history.', 'English, Spanish', 'United States, Mexico, Japan', 'Won 2 Oscars. 113 wins & 42 nominations total', 'https://m.media-amazon.com/images/M/MV5BMDIyM2E2NTAtMzlhNy00ZGUxLWI1NjgtZDY5MzhiMDc5NGU3XkEyXkFqcGc@._V1_QL75_UY562_CR7,0,380,562_.jpg', NULL, 81, 8.4, 727988, 'movie', NULL, 210460015, NULL, NULL, 5),
('tt2543164', 'Arrival', 2016, 'PG-13', '2016-11-11', 116, 'Drama, Mystery, Sci-Fi', 'Denis Villeneuve', 'Eric Heisserer, Ted Chiang', 'Amy Adams, Jeremy Renner, Forest Whitaker', 'Linguistics professor Louise Banks leads an elite team of investigators when gigantic spaceships touchdown in 12 locations around the world. As nations teeter on the verge of global war, Banks and her crew must race against time to find a way to communicate with the extraterrestrial visitors. Hoping to unravel the mystery, she takes a chance that could threaten her life and quite possibly all of mankind.', 'English, Mandarin, Russian', 'Canada, United States', 'Won 1 Oscar. 73 wins & 276 nominations total', 'https://m.media-amazon.com/images/M/MV5BMTExMzU0ODcxNDheQTJeQWpwZ15BbWU4MDE1OTI4MzAy._V1_QL75_UX380_CR0,16,380,562_.jpg', NULL, 81, 7.9, 882127, 'movie', NULL, 100546139, NULL, NULL, 3),
('tt2582802', 'Whiplash', 2014, 'R', '2014-10-15', 106, 'Drama, Music', 'Damien Chazelle', 'Damien Chazelle', 'Miles Teller, J.K. Simmons, Melissa Benoist', 'Nineteen-year-old Andrew Nieman wants to be the greatest jazz drummer in the world, in a league with Buddy Rich. This goal is despite not coming from a pedigree of greatest, musical or otherwise, with Jim, his high-school-teacher father, being a failed writer. Andrew is starting his first year at Shaffer Conservatory of Music, the best music school in the United States. At Shaffer, being the best means being accepted to study under Terence Fletcher and being asked to play in his studio band, which represents the school at jazz competitions. Based on their less than positive first meeting, Andrew is surprised that Fletcher asks him to join the band, albeit in the alternate drummer position which he is more than happy to do initially. Andrew quickly learns that Fletcher operates on fear and intimidation, never settling for what he considers less than the best each and every time. Being the best in Fletcher\'s mind does not only entail playing well, but knowing that you\'re playing well and if not what you\'re doing wrong. His modus operandi creates an atmosphere of fear and of every man or woman for him/herself within the band. Regardless, Andrew works hard to be the best. He has to figure out his life priorities and what he is willing to sacrifice to be the best. The other question becomes how much emotional abuse he will endure by Fletcher to reach that greatness, which he may believe he can only achieve with the avenues opened up by Fletcher.', 'English', 'United States', 'Won 3 Oscars. 100 wins & 144 nominations total', 'https://m.media-amazon.com/images/M/MV5BMDFjOWFkYzktYzhhMC00NmYyLTkwY2EtYjViMDhmNzg0OGFkXkEyXkFqcGc@._V1_QL75_UX380_CR0,0,380,562_.jpg', NULL, 89, 8.5, 1185509, 'movie', NULL, 14003391, NULL, NULL, 1),
('tt3315342', 'Logan', 2017, 'R', '2017-03-03', 137, 'Action, Drama, Sci-Fi', 'James Mangold', 'James Mangold, Scott Frank, Michael Green', 'Hugh Jackman, Patrick Stewart, Dafne Keen', 'In 2029 the mutant population has shrunk significantly due to genetically modified plants designed to reduce mutant powers and the X-Men have disbanded. Logan, whose power to self-heal is dwindling, has surrendered himself to alcohol and now earns a living as a chauffeur. He takes care of the ailing old Professor X whom he keeps hidden away. One day, a female stranger asks Logan to drive a girl named Laura to the Canadian border. At first he refuses, but the Professor has been waiting for a long time for her to appear. Laura possesses an extraordinary fighting prowess and is in many ways like Wolverine. She is pursued by sinister figures working for a powerful corporation; this is because they made her, with Logan\'s DNA. A decrepit Logan is forced to ask himself if he can or even wants to put his remaining powers to good use. It would appear that in the near-future, the times in which they were able put the world to rights with razor sharp claws and telepathic powers are now over.', 'English, Spanish', 'United States', 'Nominated for 1 Oscar. 29 wins & 82 nominations total', 'https://m.media-amazon.com/images/M/MV5BM2JjODdkMGMtNmY2YS00OGM2LThiY2YtZGYyNzE4Nzc2ODA0XkEyXkFqcGc@._V1_QL75_UX380_CR0,4,380,562_.jpg', NULL, 77, 8.1, 942874, 'movie', NULL, 226277068, NULL, NULL, 2),
('tt3659388', 'The Martian', 2015, 'PG-13', '2015-10-02', 144, 'Adventure, Drama, Sci-Fi', 'Ridley Scott', 'Drew Goddard, Andy Weir', 'Matt Damon, Jessica Chastain, Kristen Wiig', 'During a manned mission to Mars, Astronaut Mark Watney is presumed dead after a fierce storm and left behind by his crew. But Watney has survived and finds himself stranded and alone on the hostile planet. With only meager supplies, he must draw upon his ingenuity, wit and spirit to subsist and find a way to signal to Earth that he is alive. Millions of miles away, NASA and a team of international scientists work tirelessly to bring \"the Martian\" home, while his crewmates concurrently plot a daring, if not impossible, rescue mission. As these stories of incredible bravery unfold, the world comes together to root for Watney\'s safe return.', 'English, Mandarin', 'United States, United Kingdom, Hungary, Jordan', 'Nominated for 7 Oscars. 41 wins & 199 nominations total', 'https://m.media-amazon.com/images/M/MV5BMTc2MTQ3MDA1Nl5BMl5BanBnXkFtZTgwODA3OTI4NjE@._V1_QL75_UY562_CR0,0,380,562_.jpg', NULL, 80, 8.0, 1032684, 'movie', NULL, 228433663, NULL, NULL, 3),
('tt4154796', 'Avengers: Endgame', 2019, 'PG-13', '2019-04-26', 181, 'Action, Adventure, Sci-Fi', 'Anthony Russo, Joe Russo', 'Christopher Markus, Stephen McFeely, Stan Lee', 'Robert Downey Jr., Chris Evans, Mark Ruffalo', 'After the devastating events of Avengers: Infinity War (2018), the universe is in ruins due to the efforts of the Mad Titan, Thanos. With the help of remaining allies, the Avengers must assemble once more in order to undo Thanos\'s actions and undo the chaos to the universe, no matter what consequences may be in store, and no matter who they face...', 'English, Japanese, Xhosa, German', 'United States', 'Nominated for 1 Oscar. 71 wins & 132 nominations total', 'https://m.media-amazon.com/images/M/MV5BMTc5MDE2ODcwNV5BMl5BanBnXkFtZTgwMzI2NzQ2NzM@._V1_QL75_UX380_CR0,0,380,562_.jpg', NULL, 78, 8.4, 1497908, 'movie', NULL, 896057355, NULL, NULL, 2),
('tt4633694', 'Spider-Man: Into the Spider-Verse', 2018, 'PG', '2018-12-14', 117, 'Animation, Action, Adventure', 'Bob Persichetti, Peter Ramsey, Rodney Rothman', 'Phil Lord, Rodney Rothman', 'Shameik Moore, Jake Johnson, Hailee Steinfeld', 'Phil Lord and Christopher Miller, the creative minds behind The Lego Movie and 21 Jump Street, bring their unique talents to a fresh vision of a different Spider-Man Universe, with a groundbreaking visual style that\'s the first of its kind. \"Spider-Man(TM): Into the Spider-Verse\" introduces Brooklyn teen Miles Morales (Shameik Moore), and the limitless possibilities of the Spider-Verse, where more than one can wear the mask.', 'English, Spanish', 'United States', 'Won 1 Oscar. 85 wins & 60 nominations total', 'https://m.media-amazon.com/images/M/MV5BMjMwNDkxMTgzOF5BMl5BanBnXkFtZTgwNTkwNTQ3NjM@._V1_QL75_UX380_CR0,1,380,562_.jpg', NULL, 87, 8.4, 819638, 'movie', NULL, 190241310, NULL, NULL, 5),
('tt6751668', 'Parasite', 2019, 'R', '2019-11-08', 132, 'Drama, Thriller', 'Bong Joon Ho', 'Bong Joon Ho, Han Jin-won', 'Song Kang-ho, Lee Sun-kyun, Cho Yeo-jeong', 'The Kims - mother and father Chung-sook and Ki-taek, and their young adult offspring, son Ki-woo and daughter Ki-jung - are a poor family living in a shabby and cramped half basement apartment in a busy lower working class commercial district of Seoul. Ki-woo is the one who has dreams of getting out of poverty by one day going to university. Despite not having that university education, Ki-woo is chosen by his university student friend Min, who is leaving to go to school, to take over his tutoring job to Park Da-hye, who Min plans to date once he returns to Seoul and she herself is in university. The Parks are a wealthy family who for four years have lived in their modernistic house designed by and the former residence of famed architect Namgoong. While Mr. and Mrs. Park are all about status, Mrs. Park has a flighty, simpleminded mentality and temperament, which Min tells Ki-woo to feel comfortable in lying to her about his education to get the job. In getting the job, Ki-woo further learns that Mrs. Park is looking for an art therapist for the Parks\' adolescent son, Da-song, Ki-woo quickly recommending his professional art therapist friend \"Jessica\", really Ki-jung who he knows can pull off the scam in being the easiest liar of the four Kims. In Ki-woo also falling for Da-hye, he begins to envision himself in that house, and thus the Kims as a collective start a plan for all the Kims, like Ki-jung using assumed names, to replace existing servants in the Parks\' employ in orchestrating reasons for them to be fired. The most difficult to get rid of may be Moon-gwang, the Parks\' housekeeper who literally came with the house - she Namgoong\'s housekeeper when he lived there - and thus knows all the little nooks and crannies of it better than the Parks themselves. The question then becomes how far the Kims can take this scam in their quest to become their version of the Parks.', 'Korean, English', 'South Korea', 'Won 4 Oscars. 309 wins & 261 nominations total', 'https://m.media-amazon.com/images/M/MV5BYjk1Y2U4MjQtY2ZiNS00OWQyLWI3MmYtZWUwNmRjYWRiNWNhXkEyXkFqcGc@._V1_QL75_UX380_CR0,0,380,562_.jpg', NULL, 97, 8.5, 1200817, 'movie', NULL, 53847897, NULL, NULL, 1);

