('tt5311514', 'Your Name.', 2016, 'TV-PG', '2016-08-26', 106, 'Animation, Drama, Fantasy', 'Makoto Shinkai', 'Makoto Shinkai, Clark Cheng', 'Ryunosuke Kamiki, Mone Kamishiraishi, Ryo Narita', 'Two teenagers share a profound, magical connection upon discovering they are swapping bodies. Things manage to become even more complicated when the boy and girl decide to meet in person.', 'Japanese', 'Japan', '17 wins & 26 nominations total', 'https://m.media-amazon.com/images/M/MV5BMjI1ODZkYTgtYTY3Yy00ZTJkLWFkOTgtZDUyYWM4MzQwNjk0XkEyXkFqcGc@._V1_QL75_UX380_CR0,0,380,562_.jpg', NULL, 81, 8.4, 338000, 'movie', NULL, 5017246, NULL, NULL, 5),
('tt9426210', 'Weathering with You', 2019, 'PG-13', '2019-07-19', 112, 'Animation, Drama, Fantasy', 'Makoto Shinkai', 'Makoto Shinkai', 'Kotaro Daigo, Nana Mori, Tsubasa Honda', 'Set during a period of exceptionally rainy weather, high-school boy Hodaka Morishima runs away from his troubled rural home to Tokyo and befriends an orphan girl who can manipulate the weather.', 'Japanese', 'Japan', '13 wins & 21 nominations total', 'https://m.media-amazon.com/images/M/MV5BMmJiYWI4ZjktMzgyZS00MjBiLThmOTYtZWJmOTUzOTFkMTFiXkEyXkFqcGc@._V1_QL75_UY562_CR3,0,380,562_.jpg', NULL, 72, 7.5, 58000, 'movie', NULL, 8055433, NULL, NULL, 5),
