('tt2591814', 'The Garden of Words', 2013, 'TV-14', '2013-05-31', 46, 'Animation, Drama, Romance', 'Makoto Shinkai', 'Makoto Shinkai', 'Miyu Irino, Kana Hanazawa, Fumi Hirano', 'A 15-year-old boy and 27-year-old woman find an unlikely friendship one rainy day in the Shinjuku Gyoen National Garden.', 'Japanese', 'Japan', '4 wins & 1 nomination total', 'https://m.media-amazon.com/images/M/MV5BYjdiMDdlMDItOGM4Ny00YmE4LTk0MTEtMGRhM2Y4OWZkZDZkXkEyXkFqcGc@._V1_QL75_UX380_CR0,4,380,562_.jpg', NULL, NULL, 7.4, 54000, 'movie', NULL, NULL, NULL, NULL, 5),
('tt0983213', '5 Centimeters per Second', 2007, 'TV-PG', '2007-03-03', 63, 'Animation, Drama, Family', 'Makoto Shinkai', 'Makoto Shinkai, Steven Foster', 'Kenji Mizuhashi, Yoshimi Kondou, Satomi Hanamura', 'Told in three interconnected segments, we follow a young man named Takaki through his life as cruel winters, cold technology, and finally, adult obligations and responsibility converge to test the delicate petals of love.', 'Japanese', 'Japan', '2 wins & 2 nominations total', 'https://m.media-amazon.com/images/M/MV5BODVmZjhhYTYtYzRiOC00YzFiLThlZjMtZTQxNWY0MTI1MzlmXkEyXkFqcGc@._V1_QL75_UY562_CR8,0,380,562_.jpg', NULL, NULL, 7.5, 66000, 'movie', NULL, NULL, NULL, NULL, 5),
('tt0068646', 'The Godfather', 1972, 'R', '1972-03-24', 175, 'Crime, Drama', 'Francis Ford Coppola', 'Mario Puzo, Francis Ford Coppola', 'Marlon Brando, Al Pacino, James Caan', 'The aging patriarch of an organized crime dynasty transfers control of his clandestine empire to his reluctant son.', 'English, Italian, Latin', 'United States', 'Won 3 Oscars. 31 wins & 31 nominations total', 'https://m.media-amazon.com/images/M/MV5BNGEwYjgwOGQtYjg5ZS00Njc1LTk2ZGEtM2QwZWQ2NjdhZTE5XkEyXkFqcGc@._V1_QL75_UY562_CR8,0,380,562_.jpg', NULL, 100, 9.2, 2060000, 'movie', NULL, 136381073, NULL, NULL, 1),
('tt1675434', 'The Intouchables', 2011, 'R', '2011-11-02', 112, 'Biography, Comedy, Drama', 'Olivier Nakache, Éric Toledano', NULL, 'Olivier Nakache, Éric Toledano, Philippe Pozzo di Borgo', 'After he becomes a quadriplegic from a paragliding accident, an aristocrat hires a young man from the projects to be his caregiver.', 'French, English', 'France', 'Nominated for 1 BAFTA Award. 38 wins & 40 nominations total', 'https://m.media-amazon.com/images/M/MV5BMTYxNDA3MDQwNl5BMl5BanBnXkFtZTcwNTU4Mzc1Nw@@._V1_QL75_UX380_CR0,0,380,562_.jpg', NULL, 57, 8.5, 952000, 'movie', NULL, 10198820, NULL, NULL, 1),
('tt0108052', 'Schindler\'s List', 1993, 'R', '1994-02-04', 195, 'Biography, Drama, History', 'Steven Spielberg', 'Thomas Keneally, Steven Zaillian', 'Liam Neeson, Ralph Fiennes, Ben Kingsley', 'In German-occupied Poland during World War II, industrialist Oskar Schindler gradually becomes concerned for his Jewish workforce after witnessing their persecution by the Nazis.', 'English, Hebrew, German, Polish, Latin', 'United States', 'Won 7 Oscars. 91 wins & 49 nominations total', 'https://m.media-amazon.com/images/M/MV5BNjM1ZDQxYWUtMzQyZS00MTE1LWJmZGYtNGUyNTdlYjM3ZmVmXkEyXkFqcGc@._V1_QL75_UX380_CR0,4,380,562_.jpg', NULL, 95, 9, 1485000, 'movie', NULL, 96898818, NULL, NULL, 1);

CREATE TABLE IF NOT EXISTS `panier` (
  `id_utilisateur` int(11) NOT NULL,
  `imdb_id` varchar(12) NOT NULL,
  `date_ajout` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id_utilisateur`,`imdb_id`),
  KEY `imdb_id` (`imdb_id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `utilisateurs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `pseudo` varchar(30) NOT NULL,
  `email` varchar(255) NOT NULL,
  `mot_de_passe` varchar(255) NOT NULL,
  `date_inscription` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `pseudo` (`pseudo`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

ALTER TABLE `achats`
  ADD CONSTRAINT `achats_ibfk_1` FOREIGN KEY (`id_commande`) REFERENCES `commandes` (`id`) ON DELETE CASCADE,
  ADD CONSTRAINT `achats_ibfk_2` FOREIGN KEY (`imdb_id`) REFERENCES `films` (`imdb_id`);

ALTER TABLE `commandes`
  ADD CONSTRAINT `commandes_ibfk_1` FOREIGN KEY (`id_utilisateur`) REFERENCES `utilisateurs` (`id`) ON DELETE CASCADE;

ALTER TABLE `films`
  ADD CONSTRAINT `films_ibfk_1` FOREIGN KEY (`categorie_id`) REFERENCES `categories` (`id`);

ALTER TABLE `panier`
  ADD CONSTRAINT `panier_ibfk_1` FOREIGN KEY (`id_utilisateur`) REFERENCES `utilisateurs` (`id`) ON DELETE CASCADE,
  ADD CONSTRAINT `panier_ibfk_2` FOREIGN KEY (`imdb_id`) REFERENCES `films` (`imdb_id`) ON DELETE CASCADE;
  SET FOREIGN_KEY_CHECKS = 1;
COMMIT;

